insert into public.eleao_articles(id,category,question,answer,source,keywords) values ('guia-9','Reforma tributária','Como funciona o ano de teste da CBS e do IBS?','No comunicado conjunto RFB/CGIBS atualizado em 28 de outubro de 2026, o ano de 2026 é tratado como teste. A dispensa de recolhimento descrita depende do cumprimento das obrigações acessórias aplicáveis; consulte o comunicado e as normas e notas técnicas atualizadas para sua operação.','https://www.gov.br/receitafederal/pt-br/assuntos/noticias/2025/dezembro/comunicado-conjunto','2026 teste dispensa recolhimento obrigação acessória documento eletrônico') on conflict(id) do nothing;
insert into public.eleao_articles(id,category,question,answer,source,keywords) values ('guia-10','Simples Nacional','Quando a ME ou EPP do Simples usa a NFS-e nacional?','Segundo a Receita, a Resolução CGSN 191/2026 determina o Emissor Nacional para ME e EPP optantes que prestem serviços sujeitos à NFS-e a partir de 1º de novembro de 2026. As regras de IBS e CBS indicadas pela Receita passam a produzir efeitos para optantes a partir de 2027 nas hipóteses previstas. Confira atualizações e enquadramento.','https://www.gov.br/receitafederal/pt-br/assuntos/noticias/2026/agosto/simples-nacional-nfs-e-nacional-sera-obrigatoria-para-me-e-epp-a-partir-de-1o-de-novembro-de-2026','simples nacional nfse emissor me epp novembro 2026 2027') on conflict(id) do nothing;
insert into public.eleao_articles(id,category,question,answer,source,keywords) values ('guia-11','Escrituração','Qual é a diferença entre ECD e ECF?','A ECD corresponde à escrituração contábil digital; a ECF reúne informações contábeis e fiscais, incluindo ajustes para apuração de IRPJ e CSLL. Obrigatoriedade, exceções, leiautes e prazos dependem do período e da situação da entidade. Consulte os manuais atualizados da Receita e o profissional responsável.','https://www.gov.br/receitafederal/pt-br/centrais-de-conteudo/download/sped','ecd ecf sped escrituração contábil fiscal irpj csll') on conflict(id) do nothing;
insert into public.eleao_articles(id,category,question,answer,source,keywords) values ('guia-12','Contabilidade','Qual norma contábil devo consultar para pequenas empresas?','O CFC disponibiliza a relação de normas simplificadas, incluindo NBC TG 1000, 1001 e 1002. A escolha depende do enquadramento, exercício e demais critérios previstos na norma vigente; não se determina apenas pelo regime tributário. Confirme o texto atualizado com o profissional responsável.','https://cfc.org.br/tecnica/normas-brasileiras-de-contabilidade/normas-simplificadas-para-pmes/','nbc tg 1000 1001 1002 norma contabilidade pequena empresa microentidade') on conflict(id) do nothing;
insert into public.eleao_articles(id,category,question,answer,source,keywords) values ('guia-13','Societário','Onde conferir regras de registro de sociedade limitada?','Consulte o Manual de Registro de Sociedade Limitada do DREI e as orientações da Junta Comercial competente. Verifique a versão vigente, o contrato social e as exigências do caso antes de protocolar constituição ou alteração.','https://www.gov.br/empresas-e-negocios/pt-br/drei/legislacao/instrucoes-normativas/arquivos-instrucoes-normativas-em-vigor/anexo-iv-limitada_compilada.pdf','sociedade limitada ltda contrato social dre i junta comercial registro alteração') on conflict(id) do nothing;
insert into public.eleao_articles(id,category,question,answer,source,keywords) values ('guia-14','Contabilidade','Onde consultar orientações do CRC do Rio de Janeiro?','O CRCRJ oferece informações sobre registro e fiscalização profissional e atendimento à classe contábil. Para outras unidades da Federação, consulte o respectivo conselho regional. Verifique sempre a vigência das normas nacionais do CFC.','https://www.crc.org.br/faq/perguntas-frequentes.asp','crcrj crc conselho regional registro profissional fiscalização rio janeiro') on conflict(id) do nothing;
